import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.CmvPqeTF.js";const u=JSON.parse('{"title":"SFTP 文件管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sftp.md","filePath":"guide/sftp.md","lastUpdated":1788361893000}'),l={name:"guide/sftp.md"};function i(r,a,o,d,p,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="sftp-文件管理" tabindex="-1">SFTP 文件管理 <a class="header-anchor" href="#sftp-文件管理" aria-label="Permalink to &quot;SFTP 文件管理&quot;">​</a></h1><p>ActivityBar 底部的文件夹图标打开 SFTP 面板（底部区域），提供远端 / 本地双栏浏览与多种传输方式。面板<strong>跟随当前激活的终端标签</strong>所属连接；连接全部断开时面板自动关闭。</p><hr><h2 id="_1-面板布局" tabindex="-1">1. 面板布局 <a class="header-anchor" href="#_1-面板布局" aria-label="Permalink to &quot;1. 面板布局&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────┬─────────────────────────┐</span></span>
<span class="line"><span>│ 远端（flex 6）                  │ 本地（flex 4）           │</span></span>
<span class="line"><span>│ ┌─────────┬─────────────────┐ │ ┌─────────────────────┐ │</span></span>
<span class="line"><span>│ │ 目录树   │ 面包屑路径条      │ │ │ 面包屑路径条          │ │</span></span>
<span class="line"><span>│ │（懒加载, │ 名称 大小 修改时间 │ │ │ 名称 大小 修改时间     │ │</span></span>
<span class="line"><span>│ │ 可拖宽） │ [表头点击排序]     │ │ │ [.*] [刷新] [📂]     │ │</span></span>
<span class="line"><span>│ │         │ [刷新][⬇][🗑]     │ │ │ [⬆ 上传][🗑]         │ │</span></span>
<span class="line"><span>│ └─────────┴─────────────────┘ │ └─────────────────────┘ │</span></span>
<span class="line"><span>├───────────────────────────────┴─────────────────────────┤</span></span>
<span class="line"><span>│ ▸ 传输状态条（22px）：总进度 · 当前文件 · 合计速度 [✕ 取消] │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>远端侧</strong>：左侧懒加载目录树（宽 120–500px 可拖）+ 右侧文件表格</li><li><strong>本地侧</strong>：从主目录开始浏览；<code>.*</code> 按钮显示 / 隐藏隐藏文件；📂 在系统文件管理器中打开当前目录</li><li>双击路径条可变为输入框，手输路径回车跳转；点击面包屑某一级可直达</li><li>单击选中，<code>Ctrl / ⌘ + 点击</code> 多选</li><li>表头点击排序（目录恒排前，升 / 降序切换）</li></ul><h2 id="_2-传输的四种方式" tabindex="-1">2. 传输的四种方式 <a class="header-anchor" href="#_2-传输的四种方式" aria-label="Permalink to &quot;2. 传输的四种方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>方式</th><th>操作</th></tr></thead><tbody><tr><td>1</td><td>按钮下载</td><td>选中远端文件 → <strong>⬇ 下载所选</strong>，落到本地侧当前目录</td></tr><tr><td>2</td><td>按钮上传</td><td>选中本地文件 → <strong>⬆ 上传所选</strong>，传到远端侧当前目录</td></tr><tr><td>3</td><td>应用内拖拽</td><td>本地行拖到远端列表 = 上传；远端行拖到本地列表 = 下载；支持多选拖拽（拖拽幽灵显示 <code>+N</code>）</td></tr><tr><td>4</td><td><strong>系统拖入</strong></td><td>直接从 Finder / 资源管理器把文件拖到远端列表区域上传（原生文件拖放）</td></tr></tbody></table><blockquote><p><strong>反向拖出（远端拖到桌面）不支持</strong>：Wails v3 尚无系统级拖出能力（<code>docs/issues/0002</code>，标记不修复）。下载请用方式 1 / 3。</p></blockquote><ul><li>删除：远端 / 本地两侧均有 🗑 删除所选；远端目录会递归删除</li><li>目录传输：上传 / 下载都支持整个目录递归（自动 <code>MkdirAll</code>）</li></ul><h2 id="_3-传输进度与并发" tabindex="-1">3. 传输进度与并发 <a class="header-anchor" href="#_3-传输进度与并发" aria-label="Permalink to &quot;3. 传输进度与并发&quot;">​</a></h2><ul><li>底部 22px 常驻状态条：所有任务按字节合计的整体进度、当前文件名、合计速度（KB/s / MB/s）</li><li>有活动任务时显示 <strong>✕ 取消所有传输</strong></li><li>全部完成后 2 秒自动收起</li><li>后端并发上限 <strong>3 个传输</strong>（超出排队），32KB 块读写</li><li>传输完成自动刷新对应目录列表</li></ul><p>进度数据经 <code>sftp:progress</code> 事件实时推送（单文件百分比 / 速度，目录传输按总字量聚合）。</p><h2 id="_4-与编辑器联动" tabindex="-1">4. 与编辑器联动 <a class="header-anchor" href="#_4-与编辑器联动" aria-label="Permalink to &quot;4. 与编辑器联动&quot;">​</a></h2><p>双击远端文本文件直接进入<a href="./editor.html">远程文件编辑</a>（≤ 5MB、非二进制），无需下载到本地。</p><h2 id="_5-当前边界-如实说明" tabindex="-1">5. 当前边界（如实说明） <a class="header-anchor" href="#_5-当前边界-如实说明" aria-label="Permalink to &quot;5. 当前边界（如实说明）&quot;">​</a></h2><p>远端文件操作目前支持：<strong>浏览、读取、写入（编辑器）、删除、上传、下载、取消传输</strong>。以下操作暂不支持：</p><ul><li>新建文件 / 新建目录</li><li>重命名 / 移动</li><li>修改权限（chmod）</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./editor.html">远程文件编辑</a></li><li><a href="./../dev/architecture.html">架构总览</a> —— SFTP 并发池与进度事件的后端实现</li></ul>`,21)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
